package com.sakti.banking.dto; import com.sakti.banking.entity.*; import java.math.*; import java.time.*; public record AccountResponse(Long id,String accountNumber,AccountType accountType,AccountStatus status,BigDecimal balance,String ownerName,String ownerEmail,LocalDateTime createdAt,LocalDateTime closedAt){ public static AccountResponse from(BankAccount a){return new AccountResponse(a.getId(),a.getAccountNumber(),a.getAccountType(),a.getStatus(),a.getBalance(),a.getOwner().getFullName(),a.getOwner().getEmail(),a.getCreatedAt(),a.getClosedAt());}}